import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { createRequire } from 'node:module'
import { ListObjectVersionsCommand, DeleteObjectCommand } from '@aws-sdk/client-s3'
import { createImageCleanup, ORPHAN_GRACE_MS, ORPHAN_SWEEP_MS } from '../lib/image-cleanup.js'

const require = createRequire(import.meta.url)
const Y = require('yjs')
const key = 'notes/12345678-1234-1234-1234-123456789abc.png'
const key2 = 'notes/12345678-1234-1234-1234-123456789def.jpg'
const link = `![](/img/${key.slice('notes/'.length)})`

function fixture(t) {
    const dataDir = mkdtempSync(join(tmpdir(), 'notepad-cleanup-'))
    const docs = new Map()
    t.after(() => {
        for (const doc of docs.values()) doc.destroy()
        rmSync(dataDir, { recursive: true, force: true })
    })
    const f = {
        time: 1000000000, calls: [], errors: [], warnings: [], docs, dataDir,
        versions: [{ Key: key, VersionId: 'v1', LastModified: new Date(0) }],
        deletes: [],
    }
    f.s3 = { async send(command) {
        f.calls.push(command)
        if (command instanceof ListObjectVersionsCommand) {
            if (f.list) return f.list(command.input)
            return { Versions: [...f.versions] }
        }
        assert.ok(command instanceof DeleteObjectCommand)
        if (f.beforeDelete) await f.beforeDelete(command.input)
        f.deletes.push(command.input)
        f.versions = f.versions.filter(v => v.Key !== command.input.Key || v.VersionId !== command.input.VersionId)
        return {}
    } }
    f.options = {
        s3: f.s3, bucket: 'bucket', folder: 'notes', dataDir, docs, now: () => f.time,
        logger: { error: (...args) => f.errors.push(args), warn: (...args) => f.warnings.push(args), log() {} },
    }
    f.create = () => createImageCleanup(f.options)
    f.cleanup = f.create()
    f.state = () => JSON.parse(readFileSync(join(dataDir, 'image-orphans.json'), 'utf8')).orphanedAt
    f.saveDoc = (name, text) => {
        const doc = new Y.Doc()
        doc.getText('codemirror').insert(0, text)
        writeFileSync(join(dataDir, `${name}.bin`), Y.encodeStateAsUpdate(doc))
        doc.destroy()
    }
    return f
}

test('starts seven days at first unused observation, not upload time, and survives restart', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    const firstSeen = f.time
    assert.equal(f.state()[key], firstSeen)
    assert.equal(f.deletes.length, 0)
    f.time += ORPHAN_GRACE_MS - 1
    f.cleanup = f.create()
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    f.time++
    await f.cleanup.sweep()
    assert.deepEqual(f.deletes, [{ Bucket: 'bucket', Key: key, VersionId: 'v1' }])
    assert.deepEqual(f.state(), {})
})

test('ordinary edits and repeated restarts do not extend unused image deadlines', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    const firstSeen = f.time
    for (let day = 1; day <= 7; day++) {
        f.time += ORPHAN_GRACE_MS / 7
        const text = `Unrelated note edit on day ${day}`
        f.saveDoc('note', text)
        f.cleanup.noteReferences(text)
        f.cleanup = f.create()
        await f.cleanup.sweep()
        if (day < 7) {
            assert.equal(f.state()[key], firstSeen)
            assert.equal(f.deletes.length, 0)
        }
    }
    assert.deepEqual(f.deletes, [{ Bucket: 'bucket', Key: key, VersionId: 'v1' }])
    assert.deepEqual(f.state(), {})
    assert.equal(f.errors.length, 0)
})

test('ordinary edits need no cleanup checkpoint when there are no tracked images', t => {
    const f = fixture(t)
    mkdirSync(join(f.dataDir, 'image-orphans.json.tmp'))
    f.saveDoc('note', 'Unrelated edit')
    assert.doesNotThrow(() => f.cleanup.noteReferences('Unrelated edit'))
    assert.equal(f.errors.length, 0)
})

test('saved references in any note and live references protect images', async t => {
    const f = fixture(t)
    f.versions.push({ Key: key2, VersionId: 'v2' })
    f.saveDoc('other-tab', link)
    const live = new Y.Doc()
    live.getText('codemirror').insert(0, `/img/${key2.slice(6)}`)
    f.docs.set('live-tab', live)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS * 2
    await f.cleanup.sweep()
    assert.deepEqual(f.state(), {})
    assert.equal(f.deletes.length, 0)
    f.saveDoc('other-tab', '')
    await f.cleanup.sweep()
    assert.equal(f.state()[key], f.time)
    assert.equal(f.deletes.length, 0)
})

test('restoring and removing between sweeps resets grace, including across restart', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS - 1
    f.cleanup.noteReferences(link)
    f.cleanup.noteReferences('')
    assert.deepEqual(f.state(), {})
    f.cleanup = f.create()
    f.time++
    await f.cleanup.sweep()
    assert.equal(f.state()[key], f.time)
    assert.equal(f.deletes.length, 0)
    f.time += ORPHAN_GRACE_MS
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 1)
})

test('tracking write failure does not interrupt notes or reuse stale deadlines after restart', async t => {
    const f = fixture(t)
    const doc = new Y.Doc()
    f.docs.set('note', doc)
    const text = doc.getText('codemirror')
    const save = () => writeFileSync(join(f.dataDir, 'note.bin'), Y.encodeStateAsUpdate(doc))
    save()
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS - 1

    // Make only cleanup metadata unwritable; note persistence still works.
    const temporaryState = join(f.dataDir, 'image-orphans.json.tmp')
    mkdirSync(temporaryState)
    text.insert(0, link)
    save()
    assert.doesNotThrow(() => f.cleanup.noteReferences(text.toString()))
    assert.equal(f.errors.length, 1)
    text.delete(0, text.length)
    save()
    assert.doesNotThrow(() => f.cleanup.noteReferences(''))
    rmSync(temporaryState, { recursive: true })

    f.cleanup = f.create()
    f.time++
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    assert.equal(f.state()[key], f.time)
    f.time += ORPHAN_GRACE_MS
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 1)
})

test('failed tracking write during sweep prevents deletion until persistence recovers', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS
    const temporaryState = join(f.dataDir, 'image-orphans.json.tmp')
    mkdirSync(temporaryState)
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    assert.equal(f.errors.length, 1)
    rmSync(temporaryState, { recursive: true })
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 1)
})

test('unreadable saved documents abort cleanup without deleting expired images', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS
    writeFileSync(join(f.dataDir, 'broken.bin'), Buffer.from([255]))
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    assert.equal(f.errors.length, 1)
    assert.equal(f.state()[key], 1000000000)
})

test('missing bucket or folder never accesses storage', async t => {
    const f = fixture(t)
    for (const overrides of [{ bucket: undefined }, { folder: undefined }, { folder: '' }]) {
        await createImageCleanup({ ...f.options, ...overrides }).sweep()
    }
    assert.equal(f.calls.length, 0)
})

test('invalid tracking state safely starts a new grace period', async t => {
    const f = fixture(t)
    for (const state of ['broken json', JSON.stringify({ bucket: 'bucket', folder: 'notes', orphanedAt: { [key]: 'bad' } })]) {
        writeFileSync(join(f.dataDir, 'image-orphans.json'), state)
        f.cleanup = f.create()
        await f.cleanup.sweep()
        assert.equal(f.state()[key], f.time)
        assert.equal(f.deletes.length, 0)
        f.time += ORPHAN_GRACE_MS
    }
    assert.equal(f.warnings.length, 2)
})

test('tracking from a different storage scope does not reuse old deadlines', async t => {
    const f = fixture(t)
    writeFileSync(join(f.dataDir, 'image-orphans.json'), JSON.stringify({
        bucket: 'another-bucket', folder: 'notes', orphanedAt: { [key]: 0 },
    }))
    f.cleanup = f.create()
    await f.cleanup.sweep()
    assert.equal(f.state()[key], f.time)
    assert.equal(f.deletes.length, 0)
})

test('lists all pages and removes all versions and delete markers, but not unrelated files', async t => {
    const f = fixture(t)
    f.list = input => {
        assert.equal(input.Prefix, 'notes/')
        if (!input.KeyMarker) return {
            Versions: [{ Key: key, VersionId: 'v1' }, { Key: 'notes/backup.json', VersionId: 'keep' }],
            IsTruncated: true, NextKeyMarker: key, NextVersionIdMarker: 'v1',
        }
        assert.equal(input.KeyMarker, key)
        assert.equal(input.VersionIdMarker, 'v1')
        return {
            Versions: [{ Key: key, VersionId: 'v2' }, { Key: `elsewhere/${key.slice(6)}`, VersionId: 'keep' }],
            DeleteMarkers: [{ Key: key, VersionId: 'hidden' }],
        }
    }
    await f.cleanup.sweep()
    assert.deepEqual(Object.keys(f.state()), [key])
    f.time += ORPHAN_GRACE_MS
    await f.cleanup.sweep()
    assert.deepEqual(f.deletes.map(d => d.VersionId), ['v1', 'v2', 'hidden'])
    assert.ok(f.deletes.every(d => d.Key === key))
})

test('a later listing-page failure prevents any deletion and the next sweep retries', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS
    f.list = input => {
        if (input.KeyMarker) throw new Error('storage unavailable')
        return { Versions: f.versions, IsTruncated: true, NextKeyMarker: key, NextVersionIdMarker: 'v1' }
    }
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    assert.equal(f.errors.length, 1)
    f.list = undefined
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 1)
})

test('failed deletion retains its deadline for retry', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS
    f.beforeDelete = () => { throw new Error('delete denied') }
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    assert.equal(f.state()[key], 1000000000)
    f.beforeDelete = undefined
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 1)
})

test('references restored during listing protect expired images', async t => {
    const f = fixture(t)
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS
    f.list = () => {
        f.saveDoc('restored', link)
        return { Versions: f.versions }
    }
    await f.cleanup.sweep()
    assert.equal(f.deletes.length, 0)
    assert.deepEqual(f.state(), {})
})

test('rechecks references between deletions rather than using an old snapshot', async t => {
    const f = fixture(t)
    f.versions.push({ Key: key2, VersionId: 'v2' })
    await f.cleanup.sweep()
    f.time += ORPHAN_GRACE_MS
    f.beforeDelete = () => f.saveDoc('restored', `/img/${key2.slice(6)}`)
    await f.cleanup.sweep()
    assert.deepEqual(f.deletes.map(d => d.Key), [key])
    assert.deepEqual(f.state(), {})
})

test('overlapping sweeps are skipped', async t => {
    const f = fixture(t)
    let release
    f.list = () => new Promise(resolve => { release = resolve })
    const first = f.cleanup.sweep()
    await f.cleanup.sweep()
    assert.equal(f.calls.length, 1)
    release({ Versions: f.versions })
    await first
    assert.equal(f.errors.length, 0)
})

test('starts cleanup immediately and schedules an hourly non-blocking timer', async t => {
    const f = fixture(t)
    let callback, delay, unrefCalled = false
    const timer = { unref() { unrefCalled = true } }
    t.mock.method(globalThis, 'setInterval', (fn, ms) => { callback = fn; delay = ms; return timer })
    assert.equal(f.cleanup.start(), timer)
    assert.equal(f.calls.length, 1)
    assert.equal(delay, ORPHAN_SWEEP_MS)
    assert.equal(delay, 60 * 60 * 1000)
    assert.equal(unrefCalled, true)
    await new Promise(resolve => setImmediate(resolve))
    callback()
    await new Promise(resolve => setImmediate(resolve))
    assert.equal(f.calls.length, 2)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { extFromMime, findImageRefs, extractImageKeys } from '../lib/images.js'

test('extFromMime maps allowed types', () => {
    assert.equal(extFromMime('image/png'), 'png')
    assert.equal(extFromMime('image/jpeg'), 'jpg')
    assert.equal(extFromMime('image/gif'), 'gif')
    assert.equal(extFromMime('image/webp'), 'webp')
})

test('extFromMime rejects disallowed or empty types', () => {
    assert.equal(extFromMime('image/svg+xml'), null)
    assert.equal(extFromMime('text/plain'), null)
    assert.equal(extFromMime(undefined), null)
})

test('findImageRefs returns refs with positions and url', () => {
    const text = 'a ![](/img/x.png) b ![alt](/img/y.jpg)'
    const refs = findImageRefs(text)
    assert.equal(refs.length, 2)
    assert.deepEqual(refs[0], { from: 2, to: 17, url: '/img/x.png' })
    assert.equal(refs[1].url, '/img/y.jpg')
})

test('findImageRefs returns empty when no images', () => {
    assert.deepEqual(findImageRefs('just text'), [])
})

test('extractImageKeys pulls keys from /img/ references', () => {
    const text = '![](/img/abc.png) text ![](/img/def.webp)'
    assert.deepEqual(extractImageKeys(text), ['abc.png', 'def.webp'])
})

test('extractImageKeys returns empty when none', () => {
    assert.deepEqual(extractImageKeys('no images here'), [])
})

import { readFileSync, writeFileSync, mkdirSync } from 'fs'
import { fileURLToPath } from 'url'
import { dirname, join } from 'path'
import 'dotenv/config'
import { randomUUID } from 'crypto'
import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3'
import { getSignedUrl } from '@aws-sdk/s3-request-presigner'
import { extFromMime } from './lib/images.js'
import { createImageCleanup } from './lib/image-cleanup.js'
import express from 'express'
import { WebSocketServer } from 'ws'
import { createRequire } from 'module'
const require = createRequire(import.meta.url)
const Y = require('yjs')
const { setupWSConnection, setPersistence, docs } = require('y-websocket/bin/utils')

const __dirname = dirname(fileURLToPath(import.meta.url))
const DATA_DIR = join(__dirname, 'data')
mkdirSync(DATA_DIR, { recursive: true })

const BUCKET = process.env.B2_BUCKET
const FOLDER = process.env.B2_BUCKET_FOLDER // path prefix within the bucket; required to scope a shared bucket
const objectKey = key => FOLDER ? `${FOLDER}/${key}` : key
const s3 = new S3Client({
    endpoint: process.env.B2_ENDPOINT,
    region: process.env.B2_REGION,
    credentials: {
        accessKeyId: process.env.B2_KEY_ID,
        secretAccessKey: process.env.B2_APPLICATION_KEY,
    },
    // Recent AWS SDK versions send x-amz-checksum-* headers by default, which
    // B2 rejects ("Unsupported header 'x-amz-checksum-crc32'"). Disable them.
    // (Matches Backblaze's official v3 example, which omits forcePathStyle and
    // uses virtual-hosted style. If uploads fail with an addressing error,
    // add forcePathStyle: true as a fallback.)
    requestChecksumCalculation: 'WHEN_REQUIRED',
    responseChecksumValidation: 'WHEN_REQUIRED',
})

const imageCleanup = createImageCleanup({ s3, bucket: BUCKET, folder: FOLDER, dataDir: DATA_DIR, docs })

setPersistence({
    bindState: (docName, ydoc) => {
        const dbFile = join(DATA_DIR, docName.replace(/[^a-zA-Z0-9-_]/g, '_') + '.bin')
        try {
            Y.applyUpdate(ydoc, readFileSync(dbFile))
        } catch (e) { if (e.code !== 'ENOENT') throw e }
        imageCleanup.noteReferences(ydoc.getText('codemirror').toString())
        ydoc.on('update', () => {
            writeFileSync(dbFile, Buffer.from(Y.encodeStateAsUpdate(ydoc)))
            imageCleanup.noteReferences(ydoc.getText('codemirror').toString())
        })
    },
    writeState: () => Promise.resolve()
})

const wss = new WebSocketServer({ port: 9873 })
wss.on('connection', (ws, req) => setupWSConnection(ws, req))

const app = express()
app.use(express.static(join(__dirname, 'dist')))
app.use(express.urlencoded({ extended: false, limit: '50mb' }))

app.post('/add-to-clipboard', (req, res) => {
    const yText = docs.get('clipboard')?.getText('codemirror')
    if (!yText || !req.body.data) { res.status(400).send('Bad request'); return }
    yText.insert(yText.length, (yText.length > 0 ? '\n\n' : '') + req.body.data)
    res.send('Added to Shared Clipboard!')
})

app.post('/upload', express.raw({ type: 'image/*', limit: '10mb' }), async (req, res) => {
    const ext = extFromMime(req.headers['content-type'])
    if (!ext) { res.status(415).send('Unsupported image type'); return }
    if (!req.body || !req.body.length) { res.status(400).send('Empty body'); return }
    const key = randomUUID() + '.' + ext
    try {
        await s3.send(new PutObjectCommand({
            Bucket: BUCKET,
            Key: objectKey(key),
            Body: req.body,
            ContentType: req.headers['content-type'],
        }))
        res.json({ url: '/img/' + key })
    } catch (e) {
        console.error('Upload failed:', e)
        res.status(502).send('Upload to storage failed')
    }
})

app.get('/img/:key', async (req, res) => {
    const key = req.params.key
    if (!/^[0-9a-f-]+\.(png|jpg|gif|webp)$/i.test(key)) {
        res.status(404).send('Not found')
        return
    }
    try {
        // ?proxy streams the bytes through this origin so the browser can fetch
        // them without CORS (Backblaze sends no Access-Control-Allow-Origin).
        // Used by the chip's "copy image to clipboard" action.
        if (req.query.proxy !== undefined) {
            const out = await s3.send(new GetObjectCommand({ Bucket: BUCKET, Key: objectKey(key) }))
            res.set('Cache-Control', 'no-store')
            if (out.ContentType) res.set('Content-Type', out.ContentType)
            out.Body.on('error', err => { console.error('Image proxy stream failed:', err); res.destroy(err) })
            out.Body.pipe(res)
            return
        }
        const url = await getSignedUrl(
            s3,
            new GetObjectCommand({ Bucket: BUCKET, Key: objectKey(key) }),
            { expiresIn: 900 } // 15 minutes
        )
        res.set('Cache-Control', 'no-store')
        res.redirect(302, url)
    } catch (e) {
        console.error('Presign failed:', e)
        res.status(500).send('Failed to generate URL')
    }
})

imageCleanup.start()

app.listen(9872)

import { defineConfig } from 'vite'

export default defineConfig({
    server: {
        proxy: {
            '/upload': 'http://localhost:9872',
            '/img': 'http://localhost:9872',
        },
    },
})

import { readFileSync, writeFileSync, renameSync, readdirSync } from 'node:fs'
import { join } from 'node:path'
import { createRequire } from 'node:module'
import { createHash } from 'node:crypto'
import { ListObjectVersionsCommand, DeleteObjectCommand } from '@aws-sdk/client-s3'
import { extractImageKeys } from './images.js'

const require = createRequire(import.meta.url)
const Y = require('yjs')

export const ORPHAN_GRACE_MS = 7 * 24 * 60 * 60 * 1000
export const ORPHAN_SWEEP_MS = 60 * 60 * 1000
const IMAGE_KEY_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(png|jpg|gif|webp)$/i

export function createImageCleanup({ s3, bucket, folder, dataDir, docs = new Map(), now = Date.now, logger = console }) {
    const stateFile = join(dataDir, 'image-orphans.json')
    const prefix = `${folder}/`
    let orphanedAt = new Map()
    let running = false

    try {
        const saved = JSON.parse(readFileSync(stateFile, 'utf8'))
        if (saved.bucket === bucket && saved.folder === folder) {
            if (!saved.orphanedAt || typeof saved.orphanedAt !== 'object' || Array.isArray(saved.orphanedAt)) {
                throw new Error('Invalid orphan timestamps')
            }
            const entries = Object.entries(saved.orphanedAt)
            if (entries.some(([, timestamp]) => !Number.isFinite(timestamp) || timestamp < 0)) {
                throw new Error('Invalid orphan timestamp')
            }
            // A note may have been restored and cleared while a tracking write failed.
            if (saved.docsHash === docsHash()) orphanedAt = new Map(entries)
        }
    } catch (e) {
        // Lost or invalid tracking data starts a fresh grace period, never immediate deletion.
        if (e.code !== 'ENOENT') logger.warn('Image cleanup tracking reset:', e)
    }

    function docsHash() {
        const hash = createHash('sha256')
        for (const file of readdirSync(dataDir).filter(file => file.endsWith('.bin')).sort()) {
            hash.update(JSON.stringify(file))
            hash.update(createHash('sha256').update(readFileSync(join(dataDir, file))).digest())
        }
        return hash.digest('hex')
    }

    function saveState() {
        writeFileSync(`${stateFile}.tmp`, JSON.stringify({
            bucket, folder, docsHash: docsHash(), orphanedAt: Object.fromEntries(orphanedAt),
        }))
        renameSync(`${stateFile}.tmp`, stateFile)
    }

    function noteReferences(text) {
        let changed = false
        for (const key of extractImageKeys(text)) {
            if (orphanedAt.delete(prefix + key)) changed = true
        }
        // Keep the document checkpoint current even for ordinary edits, so a restart
        // preserves existing deadlines. A restore still resets its image between sweeps.
        if (changed || orphanedAt.size > 0) {
            try {
                saveState()
            } catch (e) {
                // The next sweep retries; a changed document hash invalidates stale state on restart.
                logger.error('Image cleanup tracking save failed:', e)
            }
        }
    }

    function referencedKeys() {
        const referenced = new Set()
        const add = doc => {
            for (const key of extractImageKeys(doc.getText('codemirror').toString())) referenced.add(prefix + key)
        }
        for (const file of readdirSync(dataDir)) {
            if (!file.endsWith('.bin')) continue
            const doc = new Y.Doc()
            try {
                Y.applyUpdate(doc, readFileSync(join(dataDir, file)))
                add(doc)
            } finally {
                doc.destroy()
            }
        }
        for (const doc of docs.values()) add(doc)
        return referenced
    }

    async function sweep() {
        if (running || !bucket) return
        if (!folder) {
            logger.warn('B2_BUCKET_FOLDER not set - skipping image cleanup')
            return
        }
        running = true
        try {
            // Finish listing before deletion so pagination never depends on a deleted version.
            const images = new Map()
            let keyMarker, versionIdMarker
            do {
                const out = await s3.send(new ListObjectVersionsCommand({
                    Bucket: bucket, Prefix: prefix, KeyMarker: keyMarker, VersionIdMarker: versionIdMarker,
                }))
                for (const version of [...(out.Versions || []), ...(out.DeleteMarkers || [])]) {
                    if (!version.Key?.startsWith(prefix) || !IMAGE_KEY_RE.test(version.Key.slice(prefix.length))) continue
                    if (!version.VersionId) throw new Error('Image version ID missing')
                    if (!images.has(version.Key)) images.set(version.Key, [])
                    images.get(version.Key).push(version.VersionId)
                }
                if (!out.IsTruncated) break
                if (!out.NextKeyMarker || (out.NextKeyMarker === keyMarker && out.NextVersionIdMarker === versionIdMarker)) {
                    throw new Error('Image listing did not advance')
                }
                keyMarker = out.NextKeyMarker
                versionIdMarker = out.NextVersionIdMarker
            } while (true)

            // An unreadable document throws and aborts the sweep rather than risking its images.
            const referenced = referencedKeys()
            for (const key of orphanedAt.keys()) {
                if (!images.has(key) || referenced.has(key)) orphanedAt.delete(key)
            }
            for (const key of images.keys()) {
                if (!referenced.has(key) && !orphanedAt.has(key)) orphanedAt.set(key, now())
            }
            saveState()

            for (const [key, versions] of images) {
                if (!orphanedAt.has(key) || now() - orphanedAt.get(key) < ORPHAN_GRACE_MS) continue
                let restored = false
                for (const versionId of versions) {
                    // Recheck after network waits, including restores in other notes.
                    if (!orphanedAt.has(key) || referencedKeys().has(key)) {
                        restored = true
                        break
                    }
                    await s3.send(new DeleteObjectCommand({ Bucket: bucket, Key: key, VersionId: versionId }))
                }
                orphanedAt.delete(key)
                if (!restored) logger.log('Swept orphan image:', key)
            }
            saveState()
        } catch (e) {
            logger.error('Image cleanup failed:', e)
        } finally {
            running = false
        }
    }

    function start() {
        void sweep()
        const timer = setInterval(() => { void sweep() }, ORPHAN_SWEEP_MS)
        timer.unref()
        return timer
    }

    return { noteReferences, sweep, start }
}

// Allowed image content-types mapped to file extensions. SVG is excluded on
// purpose to avoid stored-XSS from an SVG served same-origin.
const MIME_EXT = {
    'image/png': 'png',
    'image/jpeg': 'jpg',
    'image/gif': 'gif',
    'image/webp': 'webp',
}

export function extFromMime(mime) {
    return MIME_EXT[mime] || null
}

// Matches a markdown image, capturing the URL inside ![](...). Use only with
// String.matchAll (the /g flag makes .exec stateful across calls).
const IMAGE_MD_RE = /!\[[^\]]*\]\(([^)]+)\)/g

// Find markdown image references in text.
// Returns [{ from, to, url }] with from/to as string indices.
export function findImageRefs(text) {
    const refs = []
    for (const m of text.matchAll(IMAGE_MD_RE)) {
        refs.push({ from: m.index, to: m.index + m[0].length, url: m[1] })
    }
    return refs
}

// Extract B2 object keys from /img/<key> references in text.
export function extractImageKeys(text) {
    const keys = []
    for (const m of text.matchAll(/\/img\/([A-Za-z0-9._-]+)/g)) {
        keys.push(m[1])
    }
    return keys
}

import './style.css'
import * as Y from 'yjs'
import { WebsocketProvider } from 'y-websocket'
import { EditorView } from '@codemirror/view'
import { highlightSpecialChars, drawSelection, keymap, Decoration, WidgetType, ViewPlugin } from '@codemirror/view'
import { defaultKeymap } from '@codemirror/commands'
import { syntaxHighlighting, defaultHighlightStyle } from '@codemirror/language'
import { yCollab, yUndoManagerKeymap } from 'y-codemirror.next'
import dayjs from 'dayjs'
import { RangeSetBuilder, StateEffect } from '@codemirror/state'
import { findImageRefs } from '../lib/images.js'

// minimalSetup minus history() and historyKeymap — yCollab's Y.UndoManager handles undo
const editorSetup = [
    highlightSpecialChars(),
    drawSelection(),
    syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
    keymap.of([...defaultKeymap, ...yUndoManagerKeymap]),
]

const WS_URL = 'ws://' + location.hostname + ':9873'

// Meta doc: shared tab list
const metaDoc = new Y.Doc()
const metaProvider = new WebsocketProvider(WS_URL, 'meta', metaDoc)
const tabOrder = metaDoc.getArray('tabs')    // ordered tab IDs
const tabNames = metaDoc.getMap('tabNames')  // id → display name

// User identity
const stored = JSON.parse(sessionStorage.getItem('user') || 'null')
const user = stored ?? {
    name: 'Guest-' + Math.random().toString(36).slice(2, 6).toUpperCase(),
    color: '#' + Math.floor(Math.random() * 0xffffff).toString(16).padStart(6, '0')
}
if (!stored) sessionStorage.setItem('user', JSON.stringify(user))

// Active editor state
let activeTabId = null
let ydoc = null
let provider = null
let view = null
const beforeClear = {}

const status = document.getElementsByTagName('p')['status']

// Render images inline as <img>, or as compact chips. Saved per browser.
let chipMode = localStorage.getItem('chipMode') === '1'
const setChipMode = StateEffect.define()

function filenameFromUrl(url) {
    try { return decodeURIComponent(url.split('?')[0].split('/').pop()) || url }
    catch { return url.split('?')[0].split('/').pop() || url }
}

function openImageModal(url) {
    const overlay = document.createElement('div')
    overlay.className = 'image-modal'
    const img = document.createElement('img')
    img.src = url
    overlay.appendChild(img)
    const close = () => { overlay.remove(); document.removeEventListener('keydown', onKey) }
    const onKey = e => { if (e.key === 'Escape') close() }
    overlay.addEventListener('click', close)
    document.addEventListener('keydown', onKey)
    document.body.appendChild(overlay)
}

function blobToPng(blob) {
    return createImageBitmap(blob).then(bitmap => new Promise((resolve, reject) => {
        const canvas = document.createElement('canvas')
        canvas.width = bitmap.width
        canvas.height = bitmap.height
        canvas.getContext('2d').drawImage(bitmap, 0, 0)
        canvas.toBlob(b => b ? resolve(b) : reject(new Error('encode failed')), 'image/png')
    }))
}

// Copy plain text. Uses the async Clipboard API when available, else the legacy
// execCommand path, which (unlike image copy) still works over plain http.
async function copyText(text) {
    try {
        if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(text); return true }
    } catch { /* fall through to execCommand */ }
    const ta = document.createElement('textarea')
    ta.value = text
    ta.style.cssText = 'position:fixed;left:-9999px;top:0'
    document.body.appendChild(ta)
    ta.select()
    let ok = false
    try { ok = document.execCommand('copy') } catch { /* ignore */ }
    ta.remove()
    return ok
}

async function copyImageToClipboard(url) {
    // /img/<key> redirects to Backblaze, which has no CORS headers, so a
    // direct fetch is blocked. ?proxy streams the bytes via our own origin.
    const fetchUrl = url.startsWith('/img/')
        ? url + (url.includes('?') ? '&' : '?') + 'proxy=1'
        : url
    // Copying actual image bytes requires the async Clipboard API, which only
    // exists in a secure context (HTTPS or localhost).
    if (navigator.clipboard?.write && window.ClipboardItem) {
        try {
            const blob = await (await fetch(fetchUrl)).blob()
            const png = blob.type === 'image/png' ? blob : await blobToPng(blob)
            await navigator.clipboard.write([new ClipboardItem({ 'image/png': png })])
            return true
        } catch (e) {
            status.innerText = 'Status: Copy failed - ' + e.message
            // fall through to copying the URL instead
        }
    }
    // Can't copy the image itself - copy a shareable URL as text instead.
    const linkUrl = new URL(url.split('?')[0], location.href).href
    if (await copyText(linkUrl)) {
        status.innerText = 'Status: Copied image URL (image copy needs HTTPS/localhost)'
        return true
    }
    status.innerText = 'Status: Copy failed'
    return false
}

function buildChip(url) {
    const chip = document.createElement('span')
    chip.className = 'cm-image-chip'
    chip.title = 'Click to open'

    const icon = document.createElement('span')
    icon.className = 'chip-icon'
    icon.textContent = '🖼'

    const label = document.createElement('span')
    label.className = 'chip-label'
    label.textContent = filenameFromUrl(url)

    const copy = document.createElement('button')
    copy.className = 'chip-copy'
    copy.title = 'Copy image to clipboard'
    copy.textContent = '⧉'
    copy.addEventListener('click', async e => {
        e.stopPropagation()
        copy.textContent = '…'
        const ok = await copyImageToClipboard(url)
        copy.textContent = ok ? '✓' : '✗'
        setTimeout(() => { copy.textContent = '⧉' }, 1200)
    })

    chip.append(icon, label, copy)
    chip.addEventListener('click', () => openImageModal(url))
    return chip
}

class ImageWidget extends WidgetType {
    constructor(url, chip) { super(); this.url = url; this.chip = chip }
    eq(other) { return other.url === this.url && other.chip === this.chip }
    toDOM(view) {
        if (this.chip) return buildChip(this.url)
        const wrap = document.createElement('span')
        wrap.className = 'cm-image'
        const img = document.createElement('img')
        img.src = this.url
        img.addEventListener('load', () => view.requestMeasure())
        img.addEventListener('click', () => openImageModal(this.url))
        wrap.appendChild(img)
        return wrap
    }
    ignoreEvent() { return false }
}

function buildImageDecorations(view) {
    const builder = new RangeSetBuilder()
    for (const { from, to } of view.visibleRanges) {
        const text = view.state.doc.sliceString(from, to)
        for (const ref of findImageRefs(text)) {
            builder.add(from + ref.from, from + ref.to, Decoration.replace({ widget: new ImageWidget(ref.url, chipMode) }))
        }
    }
    return builder.finish()
}

const imageDecorations = ViewPlugin.fromClass(class {
    constructor(view) { this.decorations = buildImageDecorations(view) }
    update(update) {
        if (update.docChanged || update.viewportChanged ||
            update.transactions.some(tr => tr.effects.some(e => e.is(setChipMode))))
            this.decorations = buildImageDecorations(update.view)
    }
}, {
    decorations: v => v.decorations,
    provide: plugin => EditorView.atomicRanges.of(view => view.plugin(plugin)?.decorations || Decoration.none),
})

function createEditor(tabId) {
    if (view) { view.destroy(); view = null }
    if (provider) { provider.destroy(); provider = null }
    if (ydoc) { ydoc.destroy(); ydoc = null }

    ydoc = new Y.Doc()
    const yText = ydoc.getText('codemirror')
    provider = new WebsocketProvider(WS_URL, tabId, ydoc)
    provider.awareness.setLocalStateField('user', user)

    const remoteOnlyAwareness = new Proxy(provider.awareness, {
        get(target, prop) {
            if (prop === 'getStates') {
                return () => {
                    const states = new Map(target.getStates())
                    states.delete(target.clientID)
                    return states
                }
            }
            const value = target[prop]
            return typeof value === 'function' ? value.bind(target) : value
        }
    })

    view = new EditorView({
        extensions: [...editorSetup, EditorView.lineWrapping, imageInput, imageDecorations, yCollab(yText, remoteOnlyAwareness)],
        parent: document.getElementById('editor')
    })

    provider.on('status', ({ status: s }) => {
        lastStatus = 'Status: ' + (s === 'connected' ? 'Connected' : s === 'disconnected' ? 'Disconnected' : 'Connecting...')
        status.innerText = lastStatus
    })

    activeTabId = tabId
    renderTabs()
    view.focus()
}

function switchTab(tabId) {
    if (tabId === activeTabId) { view?.focus(); return }
    sessionStorage.setItem('activeTab', tabId)
    createEditor(tabId)
}

function addTab() {
    const id = 'tab-' + Math.random().toString(36).slice(2, 8)
    const name = 'Tab ' + (tabOrder.length + 1)
    metaDoc.transact(() => {
        tabOrder.push([id])
        tabNames.set(id, name)
    })
    switchTab(id)
}

function deleteTab(tabId) {
    if (tabOrder.length <= 1) return
    if (!confirm(`Delete tab "${tabNames.get(tabId) || tabId}"? This cannot be undone.`)) return
    const tabs = tabOrder.toArray()
    const idx = tabs.indexOf(tabId)
    if (idx === -1) return
    metaDoc.transact(() => {
        tabOrder.delete(idx, 1)
        tabNames.delete(tabId)
    })
    const remaining = tabOrder.toArray()
    switchTab(remaining[Math.min(idx, remaining.length - 1)])
}

function renderTabs() {
    const bar = document.getElementById('tab-bar')
    bar.innerHTML = ''

    tabOrder.forEach((id, idx) => {
        const tab = document.createElement('div')
        tab.className = 'tab' + (id === activeTabId ? ' active' : '')

        let wasDragged = false

        tab.addEventListener('pointerdown', e => {
            if (e.button !== 0) return
            tab.setPointerCapture(e.pointerId)
            const rect = tab.getBoundingClientRect()
            const offsetX = e.clientX - rect.left
            const offsetY = e.clientY - rect.top
            const startX = e.clientX
            const startY = e.clientY

            // Cache natural midpoints before any transforms are applied
            const tabEls = [...bar.querySelectorAll('.tab')]
            const naturalMids = tabEls.map(el => {
                const r = el.getBoundingClientRect()
                return r.left + r.width / 2
            })
            const draggedW = tab.offsetWidth + 2  // width + gap

            let ghost = null
            let dropTargetIdx = idx

            const onMove = ev => {
                if (!ghost && Math.hypot(ev.clientX - startX, ev.clientY - startY) < 5) return

                if (!ghost) {
                    wasDragged = true
                    ghost = tab.cloneNode(true)
                    ghost.classList.add('tab-ghost')
                    ghost.style.width = tab.offsetWidth + 'px'
                    document.body.appendChild(ghost)
                    tab.classList.add('tab-dragging')
                    // Enable transition only on siblings, not the dragged tab
                    tabEls.forEach(el => {
                        if (el !== tab) el.style.transition = 'transform 0.12s ease'
                    })
                }

                ghost.style.left = (ev.clientX - offsetX) + 'px'
                ghost.style.top = (ev.clientY - offsetY) + 'px'

                // Use natural midpoints so hit-testing doesn't react to its own transforms
                dropTargetIdx = tabEls.length
                for (let i = 0; i < naturalMids.length; i++) {
                    if (ev.clientX < naturalMids[i]) { dropTargetIdx = i; break }
                }

                // Slide siblings: close source gap, open destination gap
                tabEls.forEach((tabEl, i) => {
                    if (tabEl === tab) return
                    const shift = (i >= dropTargetIdx ? draggedW : 0) - (i > idx ? draggedW : 0)
                    tabEl.style.transform = shift ? `translateX(${shift}px)` : ''
                })
            }

            const onUp = () => {
                tab.removeEventListener('pointermove', onMove)
                tab.removeEventListener('pointerup', onUp)
                tab.removeEventListener('pointercancel', onUp)
                if (!ghost) return
                ghost.remove()
                tab.classList.remove('tab-dragging')
                tabEls.forEach(el => { el.style.transform = ''; el.style.transition = '' })
                let insertAt = dropTargetIdx
                if (insertAt > idx) insertAt--
                if (insertAt !== idx) {
                    const tabs = tabOrder.toArray()
                    const [moved] = tabs.splice(idx, 1)
                    tabs.splice(insertAt, 0, moved)
                    metaDoc.transact(() => {
                        tabOrder.delete(0, tabOrder.length)
                        tabOrder.insert(0, tabs)
                    })
                }
                setTimeout(() => { wasDragged = false }, 0)
            }

            tab.addEventListener('pointermove', onMove)
            tab.addEventListener('pointerup', onUp)
            tab.addEventListener('pointercancel', onUp)
        })

        const name = document.createElement('span')
        name.textContent = tabNames.get(id) || id
        tab.appendChild(name)
        tab.addEventListener('dblclick', e => {
            e.stopPropagation()
            const n = prompt('Tab name:', tabNames.get(id) || id)
            if (n?.trim()) tabNames.set(id, n.trim())
        })

        if (tabOrder.length > 1) {
            const x = document.createElement('span')
            x.className = 'tab-close'
            x.textContent = '×'
            x.addEventListener('click', e => { e.stopPropagation(); deleteTab(id) })
            tab.appendChild(x)
        }

        tab.addEventListener('click', () => { if (!wasDragged) switchTab(id) })
        bar.appendChild(tab)
    })

    const add = document.createElement('button')
    add.className = 'tab-add'
    add.textContent = '+'
    add.addEventListener('click', addTab)
    bar.appendChild(add)
}

function initTabs() {
    if (tabOrder.length === 0) {
        metaDoc.transact(() => {
            tabOrder.push(['clipboard'])
            tabNames.set('clipboard', 'Clipboard')
        })
    }
    const saved = sessionStorage.getItem('activeTab')
    const tabs = tabOrder.toArray()
    createEditor(saved && tabs.includes(saved) ? saved : tabs[0])
}

if (metaProvider.synced) {
    initTabs()
} else {
    metaProvider.once('sync', isSynced => { if (isSynced) initTabs() })
}

tabOrder.observe(renderTabs)
tabNames.observe(renderTabs)

let lastStatus = 'Status: Ready'

async function uploadImage(file) {
    status.innerText = 'Status: Uploading image...'
    try {
        const res = await fetch('/upload', {
            method: 'POST',
            body: file,
            headers: { 'content-type': file.type },
        })
        if (!res.ok) throw new Error(await res.text())
        const { url } = await res.json()
        status.innerText = lastStatus
        return url
    } catch (e) {
        status.innerText = 'Status: Image upload failed - ' + e.message
        return null
    }
}

function insertImageAt(url, pos) {
    // Put the image on its own line with a trailing blank line, so the caret
    // lands below it and there's always a navigable line after the image.
    const line = view.state.doc.lineAt(pos)
    const prefix = pos === line.from ? '' : '\n'
    const md = `${prefix}![](${url})\n`
    view.dispatch({
        changes: { from: pos, to: pos, insert: md },
        selection: { anchor: pos + md.length },
    })
    view.focus()
}

async function handleImageFiles(files, dropPos) {
    const targetTab = activeTabId
    let first = true
    for (const file of files) {
        if (!file.type.startsWith('image/')) continue
        const url = await uploadImage(file)
        if (!url) continue
        // The editor is rebuilt on tab switch; don't insert into the wrong doc.
        if (activeTabId !== targetTab) {
            status.innerText = 'Status: Image upload canceled - tab changed'
            return
        }
        const pos = first && dropPos != null ? dropPos : view.state.selection.main.head
        insertImageAt(url, pos)
        first = false
    }
}

const imageInput = EditorView.domEventHandlers({
    paste(event) {
        const files = [...(event.clipboardData?.items || [])]
            .filter(i => i.kind === 'file' && i.type.startsWith('image/'))
            .map(i => i.getAsFile())
            .filter(Boolean)
        if (files.length === 0) return false
        event.preventDefault()
        handleImageFiles(files)
        return true
    },
    drop(event, view) {
        const files = [...(event.dataTransfer?.files || [])].filter(f => f.type.startsWith('image/'))
        if (files.length === 0) return false
        event.preventDefault()
        const pos = view.posAtCoords({ x: event.clientX, y: event.clientY })
        handleImageFiles(files, pos ?? undefined)
        return true
    },
})

function insert(text) {
    const { from, to } = view.state.selection.main
    view.dispatch({
        changes: { from, to, insert: text },
        selection: { anchor: from + text.length }
    })
    view.focus()
}

document.getElementsByTagName('button')['clear'].addEventListener('click', () => {
    const yText = ydoc.getText('codemirror')
    beforeClear[activeTabId] = yText.toString()
    yText.delete(0, yText.length)
})

document.getElementsByTagName('button')['undo-clear'].addEventListener('click', () => {
    const yText = ydoc.getText('codemirror')
    if (yText.length === 0 && beforeClear[activeTabId]) yText.insert(0, beforeClear[activeTabId])
})

document.getElementsByTagName('button')['insert-date'].addEventListener('click', () =>
    insert(dayjs().format('DD-MMM-YY'))
)

document.getElementsByTagName('button')['insert-time'].addEventListener('click', () =>
    insert(`(${dayjs().format('h:mm A')}) `)
)

document.getElementsByTagName('button')['insert-date-time'].addEventListener('click', () =>
    insert(dayjs().format('DD-MMM-YY h:mm A') + ': ')
)

document.addEventListener('keydown', e => {
    if (e.key === 'F11') { e.preventDefault(); insert(`(${dayjs().format('h:mm A')}) `) }
    if (e.key === 'F12') { e.preventDefault(); insert(dayjs().format('DD-MMM-YY h:mm A') + ': ') }
})

const chipToggle = document.getElementsByTagName('button')['toggle-chips']
const updateChipToggleLabel = () => { chipToggle.textContent = chipMode ? 'Show Images' : 'Show as Chips' }
updateChipToggleLabel()
chipToggle.addEventListener('click', () => {
    chipMode = !chipMode
    localStorage.setItem('chipMode', chipMode ? '1' : '0')
    updateChipToggleLabel()
    view?.dispatch({ effects: setChipMode.of(chipMode) })
})

const imageFileInput = document.getElementsByName('image-file')[0]
document.getElementsByTagName('button')['insert-image'].addEventListener('click', () => imageFileInput.click())
imageFileInput.addEventListener('change', () => {
    if (imageFileInput.files.length) handleImageFiles([...imageFileInput.files])
    imageFileInput.value = ''
})
